// Database schema (PostgreSQL), source of the migrations generated by drizzle-kit.
// See docs/DATABASE.md for the data dictionary.
import {
  boolean,
  index,
  integer,
  pgEnum,
  pgTable,
  primaryKey,
  serial,
  text,
  timestamp,
  unique,
  uuid,
} from 'drizzle-orm/pg-core';

const id = () => uuid('id').primaryKey().defaultRandom();
const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();

// Neighbourhoods a user can follow. The pilot zones are inserted by a migration.
export const zones = pgTable(
  'zones',
  {
    id: serial('id').primaryKey(),
    name: text('name').notNull(),
    city: text('city').notNull(),
  },
  (t) => [unique('zones_name_city_unique').on(t.name, t.city)]
);

export const users = pgTable('users', {
  id: id(),
  firstName: text('first_name').notNull(),
  lastName: text('last_name').notNull(),
  email: text('email').notNull().unique(),
  password: text('password').notNull(),
  bio: text('bio').notNull().default(''),
  avatar: text('avatar').notNull().default(''),
  // Neighbourhood chosen at registration, never an address (GDPR). Null for the accounts created before.
  zoneId: integer('zone_id').references(() => zones.id, { onDelete: 'restrict' }),
  createdAt: createdAt(),
});

export const posts = pgTable(
  'posts',
  {
    id: id(),
    authorId: uuid('author_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    content: text('content').notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('posts_author_id_idx').on(t.authorId), index('posts_created_at_idx').on(t.createdAt)]
);

export const comments = pgTable(
  'comments',
  {
    id: id(),
    postId: uuid('post_id')
      .notNull()
      .references(() => posts.id, { onDelete: 'cascade' }),
    authorId: uuid('author_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    content: text('content').notNull(),
    createdAt: createdAt(),
  },
  (t) => [index('comments_post_id_idx').on(t.postId)]
);

// One like per user and per post
export const likes = pgTable(
  'likes',
  {
    postId: uuid('post_id')
      .notNull()
      .references(() => posts.id, { onDelete: 'cascade' }),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.postId, t.userId] })]
);

export const friendRequestStatus = pgEnum('friend_request_status', ['pending', 'accepted']);

export const friendRequests = pgTable(
  'friend_requests',
  {
    id: id(),
    fromId: uuid('from_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    toId: uuid('to_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    status: friendRequestStatus('status').notNull().default('pending'),
    createdAt: createdAt(),
  },
  (t) => [unique('friend_requests_from_to_unique').on(t.fromId, t.toId)]
);

export const notificationType = pgEnum('notification_type', ['like', 'comment']);

export const notifications = pgTable(
  'notifications',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    fromId: uuid('from_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    type: notificationType('type').notNull(),
    postId: uuid('post_id')
      .notNull()
      .references(() => posts.id, { onDelete: 'cascade' }),
    read: boolean('read').notNull().default(false),
    createdAt: createdAt(),
  },
  (t) => [index('notifications_user_id_idx').on(t.userId)]
);
